@Service(value="customerLoginService")
public class CustomerLoginServiceImpl implements CustomerLoginService {
	@Autowired
	private CustomerLoginRepository customerLoginRepository;

	public String authenticateCustomer(CustomerLoginDTO customerLoginDTO) 
	throws InfyBankException {
		String toRet = null;
		CustomerLoginDTO customerLoginFromRepository = 
		customerLoginRepository.getCustomerLoginByLoginName(customerLoginDTO.getLoginName());

		if (customerLoginDTO.getPassword()
												.equals(customerLoginFromRepository.getPassword())) {
			toRet = "SUCCESS";
		} else {
			throw new InfyBankException("Service.WRONG_CREDENTIALS");
		}
		return toRet;
	}
}

@SpringBootTest
public class DemoSpringBootCoreApplicationTests {
	@Autowired
	CustomerLoginService customerLoginService;

	@Test
	public void authenticateCustomerTestValidCredentials() throws InfyBankException {
		CustomerLoginDTO customer = new CustomerLoginDTO();
		customer.setLoginName("monica");
		customer.setPassword("monica123");

		String actual = customerLoginService.authenticateCustomer(customer);
		Assertions.assertEquals("SUCCESS", actual);
	}

	@Test
	public void authenticateCustomerTestInValidCredentials() throws InfyBankException {
		CustomerLoginDTO customer = new CustomerLoginDTO();
		customer.setLoginName("monica");
		customer.setPassword("monica13");

	    InfyBankException exception = Assertions.assertThrows(
			InfyBankException.class,
			() -> customerLoginService.authenticateCustomer(customer)
		);
		Assertions.assertEquals("Service.WRONG_CREDENTIALS", exception.getMessage());
	}
}

